// https://www.shadertoy.com/view/MXGcRt short melody, 2025 by jt

// Just a simple test-melody, written 2025 by Jakob Thomsen.

#define pi 3.1415926
#define tau (pi+pi)

float bing(float start, float frequency, float attenuation, float time)
{
    time -= start;
    if(time < 0.0) return 0.0;
    return sin(tau*frequency*time)*exp(-attenuation*time);
}

// start, frequency, attenuation, time
float normalized_bing(float s, float f, float a, float t) // normalized, i.e. maximal amplitude is one - https://www.shadertoy.com/view/MXGcRt short melody (jt)
{
    t -= s;
    if(t < 0.0) return 0.0;
    f *= tau;
    float t_max = (acos(s/sqrt(f*f + s*s)))/f; // time of maximum TODO: numerically stable alternative to acos?
    return sin(f*t)*exp(-a*t)/(sin(f*t_max)*exp(-a*t_max)); // normalize: bing(t)/bing(t_max)
}

float soft_clip(float scale, float sound)
{
    return tanh(scale * sound);
}

float key_to_frequency(float key)
{
    return exp2(key/12.0) * 440.0;
}

vec2 mainSound(int samp, float time)
{
    int voice[] = int[](7,0,3,5, 7,0,3,7, 5,-2,2,3, 5,-2,3,2, 0,-4,-2,0, 3,-4,-2,0, -1,-5,-1,0, 2, -5,3,2, 7,0,3,5, 7,0,3,7, 10,5,3,2, 10,5,5,7, 8,3,2,0, 8,0,3,2, 7,2,0,-2, 7,-5,3,2); // 2025 by jt
    int base[]  = int[](0,       3,      -2,       -5,        -4,       -7,         -5,        -7,         0,       3,      -2,        -5,       -4,      -7,      -5,       -1       );

    float scale = 2.0;

    float voice_start = floor(time*scale)/scale;
    int voice_index = int(floor(time*scale)) % voice.length();
    int base_index = int(floor(time*scale/4.0)) % base.length();
    float base_start = floor(time*scale/4.0)/scale*4.0;
    float sound =
        mix
        (
            /*normalized_*/bing(voice_start, key_to_frequency(float(voice[voice_index])), 7.0, time),
            soft_clip
            (
                2.0,
                mix
                (
                    /*normalized_*/bing(base_start, key_to_frequency(float(base[base_index]-12)), 1.0, time),
                    /*normalized_*/bing(base_start, key_to_frequency(float(base[base_index]-24)), 0.5, time),
